<script setup lang="ts">
import { api, friendlyError } from '@lostsky/api/client'
import { useQueries } from '@tanstack/vue-query'
import { ArrowRight, FileText, Files, UserPlus, Users } from '@lucide/vue'
import { computed } from 'vue'
const queries = useQueries({ queries: [
  { queryKey:['members'], queryFn:()=>api.get<unknown[]>('/member/index') },
  { queryKey:['posts'], queryFn:()=>api.get<unknown[]>('/postType/index') },
  { queryKey:['files-usage'], queryFn:()=>api.get<Record<string,unknown>>('/file/usage') },
  { queryKey:['notices'], queryFn:()=>api.get<unknown[]>('/notice/index') },
]})
const pending = computed(()=>queries.value.some(q=>q.isPending)); const error = computed(()=>queries.value.find(q=>q.error)?.error)
const length = (value:unknown)=>Array.isArray(value)?value.length:Number((value as Record<string,unknown>)?.total??0)
const stats=computed(()=>[
  ['成员',length(queries.value[0]?.data),Users],['岗位',length(queries.value[1]?.data),UserPlus],['文件',Number((queries.value[2]?.data as Record<string,unknown>)?.count??0),Files],['未读消息',length(queries.value[3]?.data),FileText],
])
</script>
<template><div class="dashboard"><section class="welcome"><div><p>团队运行概览</p><h2>今天要处理什么？</h2><span>先看状态，再进入具体工作。</span></div><RouterLink to="/members">管理成员 <ArrowRight :size="18" /></RouterLink></section><p v-if="error" class="error" role="alert">{{ friendlyError(error) }}</p><section class="stats" aria-label="团队数据"><article v-for="item in stats" :key="String(item[0])"><component :is="item[2]" :size="20" /><span>{{ item[0] }}</span><strong class="ls-tabular">{{ pending ? '—' : item[1] }}</strong></article></section><section class="work-grid"><article><div><h3>成员与权限</h3><p>维护成员资料、岗位和访问范围。</p></div><nav><RouterLink to="/members">成员列表<ArrowRight :size="17" /></RouterLink><RouterLink to="/roles">角色权限<ArrowRight :size="17" /></RouterLink><RouterLink to="/join-review">加入审核<ArrowRight :size="17" /></RouterLink></nav></article><article><div><h3>团队资料</h3><p>让文件和规范出现在需要它们的地方。</p></div><nav><RouterLink to="/docs">文档库<ArrowRight :size="17" /></RouterLink><RouterLink to="/files">文件空间<ArrowRight :size="17" /></RouterLink><RouterLink to="/fields">成员字段<ArrowRight :size="17" /></RouterLink></nav></article></section></div></template>
<style scoped>.dashboard{display:grid;gap:1rem}.welcome{padding:1.25rem;color:white;background:var(--sky-night);border-radius:12px}.welcome p{margin:0;color:var(--sky-lost);font-size:.76rem;font-weight:750}.welcome h2{margin:.35rem 0 0;font-size:1.65rem}.welcome span{display:block;margin-top:.35rem;color:oklch(.72 .014 210);font-size:.9rem}.welcome a{min-height:44px;display:inline-flex;align-items:center;gap:.5rem;margin-top:1.25rem;color:var(--sky-void);background:var(--afterglow);padding:0 .9rem;border-radius:8px;font-weight:700}.stats{display:grid;grid-template-columns:repeat(2,1fr);gap:.75rem}.stats article{min-height:124px;display:grid;grid-template-columns:1fr auto;align-content:space-between;padding:1rem;background:white;border:1px solid var(--line);border-radius:10px}.stats article svg{color:var(--sky-lost-strong)}.stats article span{grid-column:1;color:var(--muted-ink);font-size:.82rem}.stats article strong{grid-column:2;grid-row:1/3;align-self:end;font-size:1.8rem}.work-grid{display:grid;gap:.75rem}.work-grid article{padding:1.1rem;background:white;border:1px solid var(--line);border-radius:10px}.work-grid h3{margin:0}.work-grid p{margin:.35rem 0 1rem;color:var(--muted-ink);font-size:.88rem}.work-grid nav{border-top:1px solid var(--line)}.work-grid a{min-height:46px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);font-size:.9rem}.error{padding:.8rem;color:var(--danger);background:white;border:1px solid color-mix(in oklch,var(--danger),white 70%);border-radius:8px}@media(min-width:640px){.stats{grid-template-columns:repeat(4,1fr)}.work-grid{grid-template-columns:repeat(2,1fr)}}@media(min-width:900px){.welcome{display:flex;align-items:end;justify-content:space-between;padding:1.75rem}.welcome a{margin:0}.stats article{min-height:142px;padding:1.25rem}.work-grid article{padding:1.5rem}}</style>
